// === Tab: mySketch ===
var points = []
var s;

function setup() {
	createCanvas(700, 700);
	background(255);

	s = 30;

	for(let x = 20; x < width; x+=s) {
    for(let y = 20; y < height; y+=s) {
      points.push(new Point(x, y));
    }
  }
}

function draw() {
	background(255);

	for(let i = 0; i < points.length; i++) {
    var p = points[i];

    p.show();
    p.collapse();
    p.move();
  }
}

class Point {
	constructor(x, y) {
		this.pos = createVector(x, y);
		this.vel = createVector();
		this.acel = createVector();
		this.s = 10;
	}

	applyForce(f) {
		this.acel.add(f);
	}

	move() {
		this.vel.add(this.acel);
		this.vel.limit(10);
		this.pos.add(this.vel);
		this.acel.mult(0);
	}

	collapse() {
		var target = createVector(width/2, height/2);
		var newVel = p5.Vector.sub(target, this.pos);
		newVel.normalize();
		newVel.mult(5);

		var f = p5.Vector.sub(newVel, this.vel);
		f.limit(0.05);

		this.applyForce(f);
	}

	show() {
		noStroke();
		fill(0);
		ellipse(this.pos.x, this.pos.y, this.s, this.s);
	}
}

